Then(/^every todo in "([^"]*)" has the keys (.+)$/, function (key, keysRaw) {
  const parsed = JSON.parse(this.window.localStorage.getItem(key));
  const required = keysRaw.split(',').map((s) => s.trim().replace(/^"|"$/g, '')).filter(Boolean);
  for (const todo of parsed) {
    for (const k of required) {
      if (!(k in todo)) throw new Error(`todo ${JSON.stringify(todo)} is missing key "${k}"`);
    }
  }
});

When('the app persists the todos', function () {
  if (!this.window.todoApp || typeof this.window.todoApp.save !== 'function') {
    throw new Error('app does not expose a persist hook (window.todoApp.save)');
  }
  this.window.todoApp.save();
});

