+// --- Conformance seams (promoted checks) --------------------------------
+
+// Capture the current item-node map so a later state change can be checked
+// for node-identity preservation (the list-render stability seam).
+When('the verifier checks the list-render stability seam', function () {
+  this._renderBaseline = {};
+  var nodes = this.document.querySelectorAll('.todo-list .todo');
+  Array.prototype.forEach.call(nodes, function (li) {
+    this._renderBaseline[li.dataset.id] = li;
+  }, this);
+});
+
+Then('the list render does not destroy and recreate item list elements on a state change', function () {
+  var before = this._renderBaseline;
+  if (!before) throw new Error('stability seam: no baseline captured');
+  var items = Array.prototype.slice.call(this.document.querySelectorAll('.todo-list .todo'));
+  if (items.length === 0) throw new Error('stability seam: no items to change');
+  // A state change drives a re-render: toggle the last item's checkbox.
+  var target = items[items.length - 1];
+  var toggle = target.querySelector('.toggle');
+  toggle.checked = !toggle.checked;
+  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
+  var after = this.document.querySelectorAll('.todo-list .todo');
+  Array.prototype.forEach.call(after, function (li) {
+    var id = li.dataset.id;
+    if (before[id] && before[id] !== li) {
+      throw new Error('list render destroyed and recreated item node id=' + id);
+    }
+  });
+});
+
+When('the verifier checks the edit-mode visibility seam', function () {
+  var li = this.document.querySelector('.todo-list .todo');
+  if (!li) throw new Error('edit-mode visibility seam: no item');
+  var label = li.querySelector('.view label');
+  if (!label) throw new Error('edit-mode visibility seam: item has no label');
+  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
+  this._editLi = li;
+});
+
+Then('edit mode hides the view controls of the edited item', function () {
+  var li = this._editLi;
+  if (!li) throw new Error('edit-mode visibility seam: no edited item captured');
+  var view = li.querySelector('.view');
+  if (!view) throw new Error('edit-mode visibility seam: edited item has no .view');
+  if (!view.hidden) {
+    throw new Error('edit mode does not hide the view controls of the edited item');
+  }
+});
+
